    SELECT 1 FROM sys.foreign_keys
    WHERE name = N'fk_user_roles_user_id'
      AND parent_object_id = OBJECT_ID(N'[tax_routing].[user_roles]')
)
BEGIN
    PRINT N'Creating foreign key constraint fk_user_roles_user_id';
    ALTER TABLE [tax_routing].[user_roles]
        ADD CONSTRAINT [fk_user_roles_user_id]
        FOREIGN KEY ([user_id])
        REFERENCES [tax_routing].[app_users]([id])
        ON DELETE NO ACTION ON UPDATE NO ACTION;
END
GO

