IF NOT EXISTS (
    SELECT 1 FROM sys.objects
    WHERE name = N'ck_request_field_value_exactly_one'
      AND parent_object_id = OBJECT_ID(N'[tax_routing].[request_field_values]')
)
BEGIN
    PRINT N'Creating constraint ck_request_field_value_exactly_one on request_field_values';
    ALTER TABLE [tax_routing].[request_field_values]
        ADD CONSTRAINT ck_request_field_value_exactly_one CHECK ((CASE WHEN value_text IS NULL THEN 0 ELSE 1 END) + (CASE WHEN value_number IS NULL THEN 0 ELSE 1 END) + (CASE WHEN value_date IS NULL THEN 0 ELSE 1 END) + (CASE WHEN value_bool IS NULL THEN 0 ELSE 1 END) + (CASE WHEN value_option_id IS NULL THEN 0 ELSE 1 END) + (CASE WHEN value_json IS NULL OR value_json = '{}'::jsonb THEN 0 ELSE 1 END) = 1);
END
